import sys,json,re,os,base64,asyncio
from aiohttp import web,WSMsgType
import core
NODE=int(sys.argv[sys.argv.index('--node')+1]) if '--node' in sys.argv else 0
def err(s,m): return web.json_response({'error':m},status=s)
async def body(r):
 try: x=await r.json(); return x if isinstance(x,dict) else None
 except: return None
def auth(r):
 h=r.headers.get('Authorization',''); return core.user_for_token(h[7:] if h.startswith('Bearer ') else '')
async def api(r):
 u=auth(r)
 if r.path=='/api/health': return web.json_response({'status':'ok','node_id':NODE})
 if r.path=='/api/auth/register' and r.method=='POST':
  x=await body(r)
  if not x or not isinstance(x.get('username'),str) or not re.fullmatch(r'[A-Za-z0-9_]+',x['username']) or not isinstance(x.get('password'),str) or len(x['password'])<8:return err(400,'invalid registration')
  try:
   with core.tx() as c:
    c.execute('INSERT INTO users(username,password,display_name) VALUES(?,?,?)',(x['username'],core.hash_password(x['password']),x.get('display_name') or x['username'])); uid=c.lastrowid; t=core.issue_token(c,uid); z=c.execute('SELECT * FROM users WHERE id=?',(uid,)).fetchone()
   return web.json_response({'user':core.user_json(z),'token':t},status=201)
  except: return err(409,'duplicate username')
 if r.path=='/api/auth/login' and r.method=='POST':
  x=await body(r); c=core.connect(); z=c.execute('SELECT * FROM users WHERE username=? AND password=?',(x.get('username') if x else '',core.hash_password(x.get('password','') if x else '') )).fetchone()
  if not z:return err(401,'invalid credentials')
  t=core.issue_token(c,z['id']); c.close(); return web.json_response({'user':core.user_json(z),'token':t})
 if not u:return err(401,'unauthorized')
 if r.path=='/api/auth/me': return web.json_response({'user':core.user_json(u)})
 return await routes(r,u)
async def routes(r,u):
 p=r.path; x=await body(r) if r.method in ('POST','PATCH') else {}
 if p=='/api/workspaces' and r.method=='POST':
  if not x or not re.fullmatch(r'[a-z0-9-]{2,32}',str(x.get('slug',''))): return err(400,'invalid slug')
  try:
   with core.tx() as c:
    c.execute('INSERT INTO workspaces(slug,name,owner_id) VALUES(?,?,?)',(x['slug'],x.get('name',''),u['id'])); wid=c.lastrowid;c.execute('INSERT INTO members VALUES(?,?,?)',(wid,u['id'],'owner'));c.execute('INSERT INTO channels(workspace_id,name) VALUES(?,?)',(wid,'general'));ch=c.lastrowid;c.execute('INSERT INTO channel_members VALUES(?,?)',(ch,u['id']))
   return web.json_response({'workspace':{'id':wid,'slug':x['slug'],'name':x.get('name',''),'owner_id':u['id'],'join_mode':'open'},'general_channel':{'id':ch,'workspace_id':wid,'name':'general','is_private':False,'is_dm':False,'topic':'','is_archived':False}},status=201)
  except: return err(409,'duplicate')
 if p=='/api/workspaces':
  c=core.connect(); a=c.execute('SELECT * FROM workspaces w JOIN members m ON w.id=m.workspace_id WHERE m.user_id=?',(u['id'],)).fetchall();c.close();return web.json_response({'workspaces':[dict(z) for z in a]})
 return err(404,'not found')
app=web.Application(); app.router.add_route('*','/api/{tail:.*}',api)
app.router.add_get('/',lambda r:web.Response(text='<html><body><h1>Huddle</h1></body></html>',content_type='text/html'))
web.run_app(app,host='127.0.0.1',port=8000+NODE)
PY
python3 -m py_compile /app/core.py /app/server.py
```

