steps.message:
THOUGHT: E5 failures are entirely due to missing client-side behavior: the static hooks exist, but signup, login, workspace creation, channel creation, switching, and logout are not wired to the API. I’ll add a compact SPA controller that stores `huddle.token`, renders the current workspace/channels, surfaces errors, and supports the tested flows without dialogs.

```mswea_bash_command
python3 - <<'PY'
p='/app/static/index.html'
s=open(p).read()
start=s.index('<script>')
end=s.index('</script>',start)+9
js=r'''<script>
const $=s=>document.querySelector(s), api=async(path,opt={})=>{
 opt.headers=Object.assign({'Content-Type':'application/json','Authorization':'Bearer '+(localStorage.getItem('huddle.token')||'')},opt.headers||{});
 const r=await fetch('/api'+path,opt); let j={}; try{j=await r.json()}catch(e){}; if(!r.ok)throw Error(j.error||('HTTP '+r.status)); return j;
};
let ws=null,current=null;
function showAuth(v){$('#auth-modal').style.display=v?'block':'none';$('#workspace-create-form').style.display=v?'none':'block'}
function setError(id,e){let x=$(id);x.textContent=e.message||String(e);x.style.display='block'}
function renderChannels(chs){let box=$('#channel-list');box.innerHTML='';chs.forEach(ch=>{let b=document.createElement('button');b.className='channel-entry';b.dataset.testid='channel-entry';b.dataset.channelId=ch.id;b.dataset.channelName=ch.name;b.textContent='#'+ch.name;b.onclick=()=>openChannel(ch);box.appendChild(b)})}
async function loadWorkspace(){
 let a=await api('/workspaces'); if(!a.workspaces||!a.workspaces.length){showAuth(false);$('#workspace-create-form').style.display='block';return}
 let w=await api('/workspaces/'+a.workspaces[0].slug);$('#workspace-header').textContent=w.workspace.name;renderChannels(w.channels||[]);
 if(w.channels&&w.channels.length)openChannel(w.channels[0]);
}
async function openChannel(ch){current=ch;$('#channel-title').textContent=ch.name;$('#channel-topic').textContent=ch.topic||'';let m=await api('/channels/'+ch.id+'/messages');$('#message-list').innerHTML='';$('#channel-empty-state').textContent=m.messages.length?'':'No messages yet';(m.messages||[]).reverse().forEach(addMessage)}
function addMessage(m){let row=document.createElement('div');row.dataset.testid='message';row.innerHTML='<b>'+((m.author||{}).display_name||'User')+'</b> <span data-testid="message-body"></span>';row.querySelector('[data-testid=message-body]').textContent=m.body;$('#message-list').appendChild(row)}
$('#auth-toggle').onclick=()=>{let f=$('#auth-form'),signup=f.dataset.mode==='signup';f.dataset.mode=signup?'login':'signup';$('#auth-submit').textContent=signup?'Log in':'Sign up'};
$('#auth-form').onsubmit=async e=>{e.preventDefault();let f=e.target,x={username:f.username.value,password:f.password.value,display_name:f.display_name.value};try{let j=await api('/auth/'+(f.dataset.mode==='signup'?'register':'login'),{method:'POST',body:JSON.stringify(x)});localStorage.setItem('huddle.token',j.token);$('#current-user').textContent=j.user.username;showAuth(false);await loadWorkspace()}catch(e){setError('#auth-error',e)}};
$('#workspace-create-form').onsubmit=async e=>{e.preventDefault();try{let f=e.target,j=await api('/workspaces',{method:'POST',body:JSON.stringify({name:f.name.value,slug:f.slug.value})});$('#workspace-header').textContent=j.workspace.name;renderChannels([j.general_channel]);openChannel(j.general_channel);f.style.display='none'}catch(e){setError('#auth-error',e)}};
$('#new-channel-btn').onclick=()=>{$('#create-channel-modal').style.display='block';$('#create-channel-form').style.display='block'};
$('#create-channel-form').onsubmit=async e=>{e.preventDefault();try{let slug=(await api('/workspaces')).workspaces[0].slug,f=e.target,j=await api('/workspaces/'+slug+'/channels',{method:'POST',body:JSON.stringify({name:f.name.value,is_private:$('#create-channel-private').checked})});$('#create-channel-modal').style.display='none';await loadWorkspace();openChannel(j.channel)}catch(e){setError('#create-channel-error',e)}};
$('#logout-btn').onclick=()=>{localStorage.removeItem('huddle.token');showAuth(true)};
$('#send-btn').onclick=async()=>{if(current&&$('#message-input').value.trim()){let j=await api('/channels/'+current.id+'/messages',{method:'POST',body:JSON.stringify({body:$('#message-input').value})});addMessage(j.message);$('#message-input').value=''}};
(async()=>{if(localStorage.getItem('huddle.token')){showAuth(false);let u=await api('/auth/me');$('#current-user').textContent=u.user.username;await loadWorkspace()}else showAuth(true)})();
</script>'''
open(p,'w').write(s[:start]+js+s[end:])
